function okrNotes(opts){
  opts=opts||{};
  var o=(opts.objective||'目标').trim()||'目标';
  var krs=String(opts.keyResults||'').split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  var L=[];
  L.push('# Objective：'+o);
  L.push('');
  L.push('## Key Results');
  if(krs.length){ for(var i=0;i<krs.length;i++) L.push('KR'+(i+1)+'：'+krs[i]+'　（当前 __ → 目标 __）'); }
  else { L.push('KR1：____　（当前 __ → 目标 __）'); L.push('KR2：____　（当前 __ → 目标 __）'); }
  L.push('');
  L.push('## 关键举措');
  L.push('- ');
  L.push('');
  L.push('## 风险与依赖');
  L.push('- ');
  return L.join('\n');
}

var EXPORTS={okrNotes:okrNotes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OkrForgePure = EXPORTS; }
